	@Test
	void wrongArityIsAnEvaluationErrorForEveryFixedArityFunction() {
		for (Map.Entry<Function, Value[][]> entry : ARITIES.entrySet()) {
			Function function = entry.getKey();
			Value[] min = entry.getValue()[0];
			Value[] max = entry.getValue()[1];
			// sanity: the reference argument lists evaluate
			function.evaluate(VF, min);
			function.evaluate(VF, max);
			assertThatThrownBy(() -> function.evaluate(VF))
					.as("%s with zero arguments", function.getURI())
					.isInstanceOf(ValueExprEvaluationException.class)
					.hasMessageContaining(function.getURI());
			assertThatThrownBy(() -> function.evaluate(VF, Arrays.copyOf(min, min.length - 1)))
					.as("%s with one argument too few", function.getURI())
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> function.evaluate(VF, withExtra(max)))
					.as("%s with one argument too many", function.getURI())
					.isInstanceOf(ValueExprEvaluationException.class);
		}
		// jsonObject takes any even number of arguments, jsonArray any number
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, str("k")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, str("k"), integer(1), str("m")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new JsonObject().evaluate(VF, str("k"), integer(1), str("m"), integer(2)))
				.isEqualTo(json("{\"k\":1,\"m\":2}"));
		assertThat(new JsonArray().evaluate(VF, integer(1), integer(2), integer(3))).isEqualTo(json("[1,2,3]"));
	}

	@Test
	void unboundArgumentInAnyPositionIsAnEvaluationErrorNotANullPointerException() {
		for (Map.Entry<Function, Value[][]> entry : ARITIES.entrySet()) {
			Function function = entry.getKey();
			Value[] max = entry.getValue()[1];
			for (int i = 0; i < max.length; i++) {
				Value[] args = max.clone();
				args[i] = null;
				assertThatThrownBy(() -> function.evaluate(VF, args))
						.as("%s with unbound argument %d", function.getURI(), i)
						.isInstanceOf(ValueExprEvaluationException.class);
			}
		}
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, null, integer(1)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, str("k"), null))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonArray().evaluate(VF, integer(1), null))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void iriBlankNodeAndTripleTermArgumentsAreErrorsWhereLiteralsAreRequired() {
		List<Value> nonLiterals = List.of(VF.createIRI("http://example.org/x"), VF.createBNode("b"),
				VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createIRI("urn:o")));
		for (Value term : nonLiterals) {
			for (Map.Entry<Function, Value[][]> entry : ARITIES.entrySet()) {
				Function function = entry.getKey();
				Value[] max = entry.getValue()[1];
				for (int i = 0; i < max.length; i++) {
					boolean termPosition = (function instanceof JsonSet && i == 2)
							|| (function instanceof ArrayContains && i == 1);
					if (termPosition && !(term instanceof TripleTerm)) {
						// IRIs and blank nodes are legal JSON-encodable values in these positions
						continue;
					}
					Value[] args = max.clone();
					args[i] = term;
					assertThatThrownBy(() -> function.evaluate(VF, args))
							.as("%s with %s as argument %d", function.getURI(), term, i)
							.isInstanceOf(ValueExprEvaluationException.class);
				}
			}
			// object keys must be literals; a triple term is never representable as a JSON value
			assertThatThrownBy(() -> new JsonObject().evaluate(VF, term, integer(1)))
					.as("jsonObject key %s", term)
					.isInstanceOf(ValueExprEvaluationException.class);
		}
		Value triple = nonLiterals.get(2);
		assertThatThrownBy(() -> new JsonArray().evaluate(VF, triple)).isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, str("k"), triple))
				.isInstanceOf(ValueExprEvaluationException.class);
		// whereas an IRI as a JSON value is encoded, and matched by arrayContains
		assertThat(new JsonArray().evaluate(VF, VF.createIRI("urn:x"))).isEqualTo(json("[{\"@id\":\"urn:x\"}]"));
		assertThat(new ArrayContains().evaluate(VF, json("[{\"@id\":\"urn:x\"}]"), VF.createIRI("urn:x")))
				.isEqualTo(BooleanLiteral.TRUE);
	}

	@Test
	void unexpectedDatatypesAndMalformedLexicalFormsAreErrorsNotJavaExceptions() {
		// a non-string, non-JSON literal is never a JSON document
		for (Literal notJson : List.of(integer(1), VF.createLiteral(true), VF.createLiteral("[1]", XSD.ANYURI),
				VF.createLiteral("2024-01-01", XSD.DATE))) {
			for (Function function : List.of(new JsonValue(), new JsonQuery(), new JsonExists())) {
				assertThatThrownBy(() -> function.evaluate(VF, notJson, PATH))
						.as("%s on %s", function.getURI(), notJson)
						.isInstanceOf(ValueExprEvaluationException.class);
			}
			assertThatThrownBy(() -> new JsonKeys().evaluate(VF, notJson))
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> new JsonArrayLength().evaluate(VF, notJson))
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> new JsonSet().evaluate(VF, notJson, PATH, integer(1)))
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> new ArrayContains().evaluate(VF, notJson, integer(1)))
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> new ArrayLength().evaluate(VF, notJson))
					.isInstanceOf(ValueExprEvaluationException.class);
		}
		// numeric arguments of generateSeries: wrong datatype and malformed lexical forms
		for (Literal notNumeric : List.of(VF.createLiteral(true), str("1"), VF.createLiteral("abc", XSD.INTEGER),
				VF.createLiteral("1.5.5", XSD.DECIMAL), VF.createLiteral("1e", XSD.DOUBLE), json("1"),
				VF.createLiteral("2024-01-01", XSD.DATE))) {
			for (int position = 0; position < 3; position++) {
				Value[] args = { integer(1), integer(3), integer(1) };
				args[position] = notNumeric;
				assertThatThrownBy(() -> new GenerateSeries().evaluate(VF, args))
						.as("generateSeries with %s at %d", notNumeric, position)
						.isInstanceOf(ValueExprEvaluationException.class);
			}
		}
		// pins current behaviour: any literal's lexical form is accepted as a path (an integer literal reads as a key)
		assertThat(new JsonValue().evaluate(VF, json("{\"1\":\"one\"}"), integer(1))).isEqualTo(str("one"));
		assertThatThrownBy(() -> new JsonValue().evaluate(VF, DOC, VF.createIRI("urn:path")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void languageTaggedInputIsAcceptedForJsonTextAndPathsButNotForNumbers() {
		// pins current behaviour: a language-tagged string holding JSON is a string literal, hence accepted
		Literal taggedJson = VF.createLiteral("[1,2]", "en");
		assertThat(new ArrayLength().evaluate(VF, taggedJson)).isEqualTo(integer(2));
		assertThat(new JsonArrayLength().evaluate(VF, taggedJson)).isEqualTo(integer(2));
		assertThat(new JsonValue().evaluate(VF, taggedJson, VF.createLiteral("$[0]", "fr"))).isEqualTo(integer(1));
		assertThat(new JsonExists().evaluate(VF, taggedJson, str("$[1]"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ArrayContains().evaluate(VF, taggedJson, integer(2))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new JsonSet().evaluate(VF, taggedJson, str("$[0]"), integer(9))).isEqualTo(json("[9,2]"));
		// the language-tagged text is a plain JSON string when used as a value, with its tag preserved
		assertThat(new JsonArray().evaluate(VF, taggedJson))
				.isEqualTo(json("[{\"@value\":\"[1,2]\",\"@language\":\"en\"}]"));
		for (int position = 0; position < 3; position++) {
			Value[] args = { integer(1), integer(3), integer(1) };
			args[position] = VF.createLiteral("1", "en");
			assertThatThrownBy(() -> new GenerateSeries().evaluate(VF, args))
					.as("generateSeries with a language-tagged number at %d", position)
					.isInstanceOf(ValueExprEvaluationException.class);
		}
	}

	@Test
	void resultsAreCanonicalLiterals() {
		Literal length = (Literal) new JsonArrayLength().evaluate(VF, ARRAY);
		assertThat(length.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.INTEGER);
		assertThat(length.getLabel()).isEqualTo("2");
		assertThat(length).isEqualTo(integer(2));
		Literal arrayLength = (Literal) new ArrayLength().evaluate(VF, ARRAY);
		assertThat(arrayLength.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.INTEGER);
		assertThat(arrayLength.getLabel()).isEqualTo("2");
		Literal contains = (Literal) new ArrayContains().evaluate(VF, ARRAY, integer(1));
		assertThat(contains.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.BOOLEAN);
		assertThat(contains.getLabel()).isEqualTo("true");
		Literal exists = (Literal) new JsonExists().evaluate(VF, DOC, str("$.b"));
		assertThat(exists.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.BOOLEAN);
		assertThat(exists.getLabel()).isEqualTo("false");
		for (Literal jsonResult : List.of(new JsonQuery().evaluate(VF, DOC, PATH), new JsonKeys().evaluate(VF, DOC),
				new JsonObject().evaluate(VF, str("k"), integer(1)), new JsonArray().evaluate(VF, integer(1)),
				new JsonSet().evaluate(VF, DOC, PATH, integer(1)),
				new GenerateSeries().evaluate(VF, integer(1), integer(2)))) {
			assertThat(jsonResult.getCoreDatatype()).isEqualTo(CoreDatatype.RDF.JSON);
			assertThat(jsonResult.getLanguage()).isEmpty();
			// canonical form: no whitespace, re-parsing and re-writing is the identity
			assertThat(JsonSupport.write(JsonSupport.parse(jsonResult.getLabel()))).isEqualTo(jsonResult.getLabel());
			assertThat(jsonResult.getLabel()).doesNotContain(" ");
		}
		// scalar extraction uses the canonical RDF4J lexical forms
		assertThat(((Literal) new JsonValue().evaluate(VF, json("[1e2]"), str("$[0]"))).getLabel()).isEqualTo("100.0");
		assertThat(((Literal) new JsonValue().evaluate(VF, json("[007]"), str("$[0]"))).getLabel()).isEqualTo("7");
		assertThat(((Literal) new JsonValue().evaluate(VF, json("[true]"), str("$[0]"))).getLabel()).isEqualTo("true");
		assertThat(((Literal) new JsonValue().evaluate(VF, json("[2.50]"), str("$[0]"))).getLabel()).isEqualTo("2.50");
	}

	@Test
	void repeatedAndConcurrentEvaluationGivesIdenticalResults() throws Exception {
		// enough distinct documents and paths to overflow and clear the shared parse and path caches repeatedly
		int distinct = 1500;
		List<Literal> documents = new ArrayList<>(distinct);
		List<Literal> paths = new ArrayList<>(distinct);
		List<Literal> arrays = new ArrayList<>(distinct);
		for (int i = 0; i < distinct; i++) {
			documents.add(json("{\"k" + i + "\":" + i + ",\"l\":[" + i + "," + (i + 1) + "],\"s\":\"v" + i + "\"}"));
			paths.add(str("$.k" + i));
			arrays.add(json("[" + i + ",\"v" + i + "\"]"));
		}
		Runnable round = () -> {
			for (int i = 0; i < distinct; i++) {
				Literal document = documents.get(i);
				assertThat(new JsonValue().evaluate(VF, document, paths.get(i))).isEqualTo(integer(i));
				assertThat(new JsonValue().evaluate(VF, document, str("$.l[-1]"))).isEqualTo(integer(i + 1));
				assertThat(new JsonExists().evaluate(VF, document, paths.get(i))).isEqualTo(BooleanLiteral.TRUE);
				assertThat(new JsonArrayLength().evaluate(VF, document, str("$.l"))).isEqualTo(integer(2));
				assertThat(new JsonQuery().evaluate(VF, document, str("$.l")))
						.isEqualTo(json("[" + i + "," + (i + 1) + "]"));
				assertThat(new ArrayContains().evaluate(VF, arrays.get(i), integer(i))).isEqualTo(BooleanLiteral.TRUE);
				assertThat(new ArrayContains().evaluate(VF, arrays.get(i), str("v" + i)))
						.isEqualTo(BooleanLiteral.TRUE);
				assertThat(new ArrayContains().evaluate(VF, arrays.get(i), integer(i + 1)))
						.isEqualTo(BooleanLiteral.FALSE);
				assertThat(new JsonSet().evaluate(VF, document, str("$.s"), integer(0)))
						.isEqualTo(json("{\"k" + i + "\":" + i + ",\"l\":[" + i + "," + (i + 1) + "],\"s\":0}"));
				assertThat(new JsonValue().evaluate(VF, document, str("$.s"))).isEqualTo(str("v" + i));
				assertThat(new GenerateSeries().evaluate(VF, integer(i), integer(i + 1)))
						.isEqualTo(json("[" + i + "," + (i + 1) + "]"));
			}
		};
		// sequentially twice: identical results
		round.run();
		round.run();
		int threads = 8;
		ExecutorService executor = Executors.newFixedThreadPool(threads);
		try {
			List<Future<?>> futures = new ArrayList<>();
			for (int t = 0; t < threads; t++) {
				futures.add(executor.submit(() -> {
					round.run();
					round.run();
				}));
			}
			for (Future<?> future : futures) {
				future.get(5, TimeUnit.MINUTES);
			}
		} finally {
			executor.shutdownNow();
		}
	}

	@Test
	void functionsAreRegisteredByIriAndListedInTheServiceFiles() throws IOException {
		Map<IRI, Class<? extends Function>> scalar = Map.of(JSONF.jsonValue, JsonValue.class, JSONF.jsonQuery,
				JsonQuery.class, JSONF.jsonExists, JsonExists.class, JSONF.jsonKeys, JsonKeys.class,
				JSONF.jsonArrayLength, JsonArrayLength.class, JSONF.jsonObject, JsonObject.class, JSONF.jsonArray,
				JsonArray.class, JSONF.jsonSet, JsonSet.class, ARRAYF.arrayContains, ArrayContains.class,
				ARRAYF.arrayLength, ArrayLength.class);
		List<String> functionServices = serviceEntries(FUNCTION_SERVICE);
		for (Map.Entry<IRI, Class<? extends Function>> entry : scalar.entrySet()) {
			assertThat(FunctionRegistry.getInstance().get(entry.getKey().stringValue())).as(entry.getKey().toString())
					.isPresent()
					.get()
					.isInstanceOf(entry.getValue());
			assertThat(functionServices).as(entry.getValue().getName()).contains(entry.getValue().getName());
		}
		assertThat(FunctionRegistry.getInstance().get(ARRAYF.generateSeries.stringValue())).isPresent()
				.get()
				.isInstanceOf(GenerateSeries.class);
		assertThat(functionServices).contains(GenerateSeries.class.getName());
		// the set-returning functions are tuple functions, found through their own registry and service file
		Map<IRI, Class<? extends TupleFunction>> tuple = Map.of(ARRAYF.unnest, UnnestTupleFunction.class,
				ARRAYF.unnestWithOrdinality, UnnestWithOrdinalityTupleFunction.class, ARRAYF.generateSeries,
				GenerateSeriesTupleFunction.class);
		List<String> tupleServices = serviceEntries(TUPLE_FUNCTION_SERVICE);
		for (Map.Entry<IRI, Class<? extends TupleFunction>> entry : tuple.entrySet()) {
			assertThat(TupleFunctionRegistry.getInstance().get(entry.getKey().stringValue()))
					.as(entry.getKey().toString())
					.isPresent()
					.get()
					.isInstanceOf(entry.getValue());
			assertThat(tupleServices).as(entry.getValue().getName()).contains(entry.getValue().getName());
		}
		// unnest is not a scalar function and arrayContains is not a tuple function
		assertThat(FunctionRegistry.getInstance().get(ARRAYF.unnest.stringValue())).isEmpty();
		assertThat(TupleFunctionRegistry.getInstance().get(ARRAYF.arrayContains.stringValue())).isEmpty();
		// lookups are exact: the namespace alone or a different case does not resolve
		assertThat(FunctionRegistry.getInstance().get(JSONF.NAMESPACE)).isEmpty();
		assertThat(FunctionRegistry.getInstance().get(JSONF.NAMESPACE + "JSONVALUE")).isEmpty();
	}

	@Test
	void vocabularyConstantsMatchTheFunctionUris() {
		assertThat(new JsonValue().getURI()).isEqualTo(JSONF.jsonValue.stringValue());
		assertThat(new JsonQuery().getURI()).isEqualTo(JSONF.jsonQuery.stringValue());
		assertThat(new JsonExists().getURI()).isEqualTo(JSONF.jsonExists.stringValue());
		assertThat(new JsonKeys().getURI()).isEqualTo(JSONF.jsonKeys.stringValue());
		assertThat(new JsonArrayLength().getURI()).isEqualTo(JSONF.jsonArrayLength.stringValue());
		assertThat(new JsonObject().getURI()).isEqualTo(JSONF.jsonObject.stringValue());
		assertThat(new JsonArray().getURI()).isEqualTo(JSONF.jsonArray.stringValue());
		assertThat(new JsonSet().getURI()).isEqualTo(JSONF.jsonSet.stringValue());
		assertThat(new ArrayContains().getURI()).isEqualTo(ARRAYF.arrayContains.stringValue());
		assertThat(new ArrayLength().getURI()).isEqualTo(ARRAYF.arrayLength.stringValue());
		assertThat(new GenerateSeries().getURI()).isEqualTo(ARRAYF.generateSeries.stringValue());
		assertThat(new GenerateSeriesTupleFunction().getURI()).isEqualTo(ARRAYF.generateSeries.stringValue());
		assertThat(new UnnestTupleFunction().getURI()).isEqualTo(ARRAYF.unnest.stringValue());
		assertThat(new UnnestWithOrdinalityTupleFunction().getURI())
				.isEqualTo(ARRAYF.unnestWithOrdinality.stringValue());
		// every constant lives in its namespace and uses the documented prefix
		for (IRI iri : List.of(JSONF.jsonValue, JSONF.jsonQuery, JSONF.jsonExists, JSONF.jsonKeys,
				JSONF.jsonArrayLength, JSONF.jsonObject, JSONF.jsonArray, JSONF.jsonSet)) {
			assertThat(iri.getNamespace()).isEqualTo(JSONF.NAMESPACE);
			assertThat(JSONF.NS.getPrefix()).isEqualTo("jsonf");
		}
		for (IRI iri : List.of(ARRAYF.arrayContains, ARRAYF.arrayLength, ARRAYF.generateSeries, ARRAYF.unnest,
				ARRAYF.unnestWithOrdinality)) {
			assertThat(iri.getNamespace()).isEqualTo(ARRAYF.NAMESPACE);
			assertThat(ARRAYF.NS.getPrefix()).isEqualTo("arrf");
		}
	}

	private static List<String> serviceEntries(String resource) throws IOException {
		List<String> entries = new ArrayList<>();
		Enumeration<URL> resources = JsonFamilyContractTest.class.getClassLoader().getResources(resource);
		while (resources.hasMoreElements()) {
			URL url = resources.nextElement();
			try (BufferedReader reader = new BufferedReader(
					new InputStreamReader(url.openStream(), StandardCharsets.UTF_8))) {
				String line;
				while ((line = reader.readLine()) != null) {
					String trimmed = line.trim();
					if (!trimmed.isEmpty() && !trimmed.startsWith("#")) {
						entries.add(trimmed);
					}
				}
			}
		}
		assertThat(entries).as(resource).isNotEmpty();
		return entries;
	}
